function CourseCard({ course }) {
  return <article className="course-card"><Link to={`/courses/${course.id}`} className="course-image"><img src={course.image} alt=""/><span className="course-level">{course.level}</span><button aria-label="Save course"><Heart/></button></Link><div className="course-body"><div className="course-category" style={{color:course.color}}>{course.category}</div><Link to={`/courses/${course.id}`}><h3>{course.title}</h3></Link><p className="instructor">Practical video course · Lifetime access</p><div className="course-meta"><span><CirclePlay size={15}/> Video lessons</span><span><Award size={15}/> Final outcome</span></div><div className="course-bottom"><strong>From ${course.packagePrice}<small> package</small></strong><Link to={`/courses/${course.id}`}>View course <ChevronRight size={15}/></Link></div></div></article>;
}

function Courses() {
  const [query,setQuery] = useState(''); const [category,setCategory] = useState('All');
  const filtered = courses.filter(c => (category==='All'||c.category===category) && `${c.title} ${c.instructor} ${c.category}`.toLowerCase().includes(query.toLowerCase()));
  return <><PageHero kicker="Globe Online Courses" title="Courses built for real skills" text="Choose from practical, video-based courses in office work, technology, design, and marketing. Start from the basics and finish with work you can use." />
    <section className="catalog-facts"><div className="container"><span><b>10</b> courses</span><span><b>4</b> categories</span><span><b>6</b> packages</span><span><Check/> Video lessons</span><span><Check/> Final projects</span></div></section>
    <section className="section compact"><div className="container"><div className="filter-bar"><div className="search-field"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search courses and skills..."/></div><div className="select-wrap"><select value={category} onChange={e=>setCategory(e.target.value)}><option>All</option>{[...new Set(courses.map(c=>c.category))].map(x=><option key={x}>{x}</option>)}</select><ChevronDown/></div></div><div className="results-line"><strong>{filtered.length} courses</strong><span>Package access starts from $3</span></div><div className="course-grid course-grid-full">{filtered.map(c=><CourseCard key={c.id} course={c}/>)}</div>{filtered.length===0&&<Empty text="No courses match your search."/>}</div></section>
  </>;
}

